plate-columns:230px minmax(0,1fr) 170px;max-width:1536px;margin:auto;min-height:calc(100vh - 160px)}.rail{position:sticky;top:76px;align-self:start;height:calc(100vh - 76px);overflow:auto;padding:30px 20px;border-right:1px solid var(--boundary)}.rail details>summary{display:none}.rail label{font-size:13px;color:var(--secondary);display:block;margin:0 0 6px}.rail input{width:100%;font-size:13px}.rail #search-status{font-size:12px;margin:6px 0 24px;color:var(--secondary);min-height:20px}.rail nav h2{font-family:Inter;font-size:12px;font-weight:650;margin:22px 8px 6px;color:var(--secondary);letter-spacing:0}.rail nav a{display:block;color:var(--content);font-size:13px;text-decoration:none;padding:7px 9px;margin:2px 0;min-height:32px;border:1px solid transparent;border-radius:6px}.rail nav a[aria-current=page]{background:var(--container);border-color:var(--boundary);color:var(--action)}.rail nav a:hover{color:var(--action)}.rail-foot{font-size:12px;color:var(--secondary);margin:36px 8px 0}main{padding:60px clamp(24px,4vw,64px) 90px;min-width:0}main>article{max-width:76ch;margin:auto}.toc{position:sticky;top:76px;align-self:start;padding:60px 20px 24px 0}.toc p{font-size:12px;color:var(--secondary)}.toc a{font-size:12px;display:block;padding:6px 0;color:var(--secondary);text-decoration:none}.toc a:hover{color:var(--action)}.lead{font-size:1.2rem;line-height:1.6;max-width:58ch}.intro-art{display:block;width:100%;aspect-ratio:1672/941;object-fit:cover;border-radius:12px;margin:34px 0 10px}.caption{font-size:12px;color:var(--secondary)}.rule{margin:32px 0;border:0;border-top:1px solid var(--boundary)}.statement{font-family:'Space Grotesk';font-size:clamp(1.5rem,3vw,2.3rem);line-height:1.3;max-width:26ch;margin:30px 0}.evidence-note{background:var(--container);padding:18px 20px;border:1px solid var(--boundary);border-radius:12px;font-size:14px;margin:24px 0}.evidence-note p:last-child{margin:0}.scope{color:var(--secondary);font-size:13px}.component-list{list-style:none;padding:0}.component-list li{padding:16px 0;border-bottom:1px solid var(--boundary)}.component-list a{font-size:1.1rem}.component-list p{font-size:13px;color:var(--secondary);margin:6px 0 0}.status-chip{display:inline-block;border:1px solid var(--boundary);color:var(--secondary);border-radius:6px;font-size:12px;padding:2px 7px;margin-right:8px;vertical-align:middle}.states{list-style:none;display:flex;flex-wrap:wrap;gap:8px;padding:0}.states li{background:var(--container);border:1px solid var(--boundary);border-radius:6px;padding:4px 10px;font-size:13px;margin:0}.demo{margin:26px 0;background:var(--container);border:1px solid var(--boundary);border-radius:12px;padding:22px}.demo-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}.demo-head p{margin:0;font-size:13px;color:var(--secondary)}.demo button{min-height:36px}.fixture-controls{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}.fixture-controls label{font-size:13px;display:flex;gap:8px;align-items:center}.fixture-output{border-top:1px solid var(--boundary);padding-top:12px;margin-top:18px}.fixture-output summary{font-size:13px;color:var(--action)}.fixture-output pre{max-height:260px;overflow:auto}.fixture-summary{font-size:13px;color:var(--secondary);margin:14px 0 0}.surface-popup>h1{font-family:Inter;font-size:20px;letter-spacing:0;margin:0 0 8px}.surface-popup[data-mode=closed]{display:none}.surface-popup>p{font-size:13px}.surface-controls{display:flex;flex-direction:column;gap:6px}.surface-controls button{display:block;width:100%;text-align:left}.control-label{display:block;font-size:14px;overflow-wrap:anywhere}.control-detail{display:block;font-size:12px;color:var(--control-detail)}.control-detail:empty{display:none}.surface-bar{display:flex;gap:8px;flex-wrap:wrap;align-items:stretch}.surface-bar .surface-status{width:100%;font-size:12px;color:var(--secondary)}.surface-bar button{flex:1 1 100px;min-width:0}.window-preview{margin:0;background:var(--page);border-radius: